-- v134 · Hora de Catum — base do termômetro (copy primeiro)
-- Pode rodar mais de uma vez. Tempos de referência vêm da planilha tempo_humano_referencia.xlsx (30/10/2026):
-- ESTIMATIVAS de planejamento, nenhuma validada com amostra da SD. Minutos de trabalho humano ATIVO.

-- 1) tempos humanos de referência (versionados)
create table if not exists public.pd_ref_tempos (
  versao       text not null default '2026-10-30',
  codigo       text not null,
  categoria    text,
  tarefa       text not null,
  rapido_min   numeric,
  medio_min    numeric,
  longo_min    numeric,
  unidade      text,
  prep_min     numeric,
  exec_min     numeric,
  revisao_min  numeric,
  evidencia    text,
  fontes       text,
  fora_escopo  text,
  aproxima_longo text,
  prazo_calendario_dias numeric,   -- só consulta; não entra na conta
  ativo        boolean not null default true,
  primary key (versao, codigo)
);
alter table public.pd_ref_tempos enable row level security;
drop policy if exists pd_ref_tempos_le on public.pd_ref_tempos;
create policy pd_ref_tempos_le on public.pd_ref_tempos for select to authenticated using (true);

on conflict (versao, codigo) do nothing;

-- 2) motivo de cada correção (erro da IA | mudança de direção | briefing ambíguo) e minutos humanos gastos
create table if not exists public.pd_catum_motivos (
  item_id     uuid primary key,                 -- approval_items.id
  motivo      text not null check (motivo in ('erro_ia','mudanca_direcao','briefing_ambiguo')),
  humano_min  numeric,                          -- minutos de trabalho humano na correção (opcional)
  por         uuid references public.profiles(id) on delete set null,
  em          timestamptz not null default now()
);
alter table public.pd_catum_motivos enable row level security;
drop policy if exists pd_catum_motivos_eq on public.pd_catum_motivos;
create policy pd_catum_motivos_eq on public.pd_catum_motivos for select to authenticated using (true);
